public class WarehouseInfo
{
    public string WarehouseId { get; set; } = "WH-001";
    public string WarehouseName { get; set; } = "Warehouse A";

    public static readonly List<WarehouseInfo> AvailableWarehouses =
    [
        new() { WarehouseId = "WH-001", WarehouseName = "Warehouse A" },
        new() { WarehouseId = "WH-002", WarehouseName = "Warehouse B" },
        new() { WarehouseId = "WH-003", WarehouseName = "Warehouse C" },
    ];
}

namespace sv_2aebd3888f364abbb46ba141fa0939f6.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Components subscribe to <see cref="OnAlertCountChanged"/> for cross-component
/// notifications. Polling is managed by the consuming component that calls
/// <see cref="StartPolling"/>/<see cref="StopPolling"/>.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private string _currentWarehouseId = string.Empty;

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired whenever the alert count changes.  Subscribers MUST wrap
    /// <c>StateHasChanged</c> in <c>InvokeAsync</c> because this fires
    /// from a timer thread, not the Blazor sync context.
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>Simulates a database query for items below minimum stock levels.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    public void StartPolling(string warehouseId)
    {
        StopPolling();
        _currentWarehouseId = warehouseId;
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    public void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void UpdateWarehouse(string warehouseId)
    {
        if (_timer is not null)
        {
            StartPolling(warehouseId);
        }
        else
        {
            _currentWarehouseId = warehouseId;
        }
    }

    /// <summary>Force an immediate refresh (e.g. on warehouse change).</summary>
    public async Task RefreshAsync(string warehouseId)
    {
        _currentWarehouseId = warehouseId;
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire once immediately so the UI isn't empty until the first tick.
        CurrentAlertCount = await GetLowStockCountAsync(_currentWarehouseId);
        OnAlertCountChanged?.Invoke();

        while (_timer is not null && await _timer.WaitForNextTickAsync(ct))
        {
            CurrentAlertCount = await GetLowStockCountAsync(_currentWarehouseId);
            OnAlertCountChanged?.Invoke();
        }
    }

    public void Dispose()
    {
        StopPolling();
    }
}

