@using sv_2aebd3888f364abbb46ba141fa0939f6.Services
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@rendermode InteractiveServer

<div class="d-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold">Warehouse:</label>
    <select class="form-select form-select-sm" style="width:auto"
            value="@_selectedId" @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseInfo.AvailableWarehouses)
        {
            <option value="@wh.WarehouseId">@wh.WarehouseName</option>
        }
    </select>
</div>

@code {
    private string _selectedId = "WH-001";

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? "WH-001";
        var selected = WarehouseInfo.AvailableWarehouses
            .First(w => w.WarehouseId == _selectedId);

        // Push the new value to every [CascadingParameter] subscriber.
        await WarehouseSource.NotifyChangedAsync(selected);
    }
}

@using sv_2aebd3888f364abbb46ba141fa0939f6.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<span class="badge bg-danger rounded-pill ms-1" style="@(AlertService.CurrentAlertCount == 0 ? "display:none" : "")">
    @AlertService.CurrentAlertCount
</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Wrap in InvokeAsync because the event fires from a timer thread.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _handler;
    }
}

